import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
from scipy.signal import find_peaks
from scipy.optimize import curve_fit
import os

def load_trajectory(data_path):
    df = pd.read_csv(data_path)
    return df

def extract_envelope_and_fit(df):
    """Find oscillation peaks and fit exponential decay to their envelope."""
    time = df['time'].values
    x = df['x'].values
    
    # Find peaks of absolute displacement
    abs_x = np.abs(x)
    peaks, _ = find_peaks(abs_x, distance=10)
    
    if len(peaks) < 3:
        print("Not enough peaks to fit envelope - may be non-oscillatory")
        return None, None
    
    peak_times = time[peaks]
    peak_amplitudes = abs_x[peaks]
    
    # Fit exponential decay: A * exp(-t/tau) + C
    def exp_decay(t, A, tau, C):
        return A * np.exp(-t / tau) + C
    
    try:
        popt, pcov = curve_fit(
            exp_decay, peak_times, peak_amplitudes,
            p0=[peak_amplitudes[0], 2.0, peak_amplitudes[-1]],
            maxfev=5000
        )
        A, tau, C = popt
        print(f"  Damping timescale tau = {tau:.2f} Gyr")
        print(f"  Residual amplitude C  = {C:.3f} kpc")
        return (A, tau, C), (peak_times, peak_amplitudes)
    except RuntimeError:
        print("  Fit did not converge")
        return None, (peak_times, peak_amplitudes)

def plot_trajectory_with_envelope(df, fit_params, peak_data, mbh_label):
    time = df['time'].values
    x = df['x'].values
    peak_times, peak_amplitudes = peak_data
    
    fig, ax = plt.subplots(figsize=(10, 5))
    ax.plot(time, x, label='BH position', linewidth=1, alpha=0.8)
    ax.scatter(peak_times, peak_amplitudes, color='orange', 
               s=20, zorder=5, label='Peaks')
    ax.scatter(peak_times, -peak_amplitudes, color='orange', s=20, zorder=5)
    
    if fit_params is not None:
        A, tau, C = fit_params
        t_fit = np.linspace(peak_times[0], peak_times[-1], 300)
        envelope = A * np.exp(-t_fit / tau) + C
        ax.plot(t_fit,  envelope, 'r--', label=f'Envelope (τ={tau:.2f} Gyr)')
        ax.plot(t_fit, -envelope, 'r--')
    
    ax.axhline(0, color='black', linewidth=0.8, linestyle=':')
    ax.set_xlabel('Time [Gyr]')
    ax.set_ylabel('x [kpc]')
    ax.set_title(f'BH Trajectory — $M_{{BH}}$ = {mbh_label}')
    ax.legend()
    ax.grid(True, alpha=0.3)
    plt.tight_layout()
    plt.show()

# --- Run this for each simulation ---
runs = [
    ("resources/data/simulation_20260418_174917/particle_trajectory.csv",  "1e6 Msun"),
    ("resources/data/simulation_20260418_181241/particle_trajectory.csv",  "5e6 Msun"),
    ("resources/data/simulation_20260418_182738/particle_trajectory.csv",  "1e7 Msun"),
    ("resources/data/simulation_20260418_180232/particle_trajectory.csv",  "5e7 Msun"),
   
    # add more as you run them
]

results = []  # will hold (Mbh, tau) pairs for the summary plot

for path, label in runs:
    if not os.path.exists(path):
        print(f"Missing: {path}")
        continue
    print(f"\n--- {label} ---")
    df = load_trajectory(path)
    fit_params, peak_data = extract_envelope_and_fit(df)
    if peak_data is not None:
        plot_trajectory_with_envelope(df, fit_params, peak_data, label)
    if fit_params is not None:
        tau = fit_params[1]
        mbh_val = float(label.split()[0])
        results.append((mbh_val, tau))

# --- Summary plot: tau vs Mbh ---
if len(results) > 1:
    mbh_vals, taus = zip(*results)
    plt.figure(figsize=(7, 5))
    plt.plot(mbh_vals, taus, 'o-')
    plt.xscale('log')
    plt.yscale('log')
    plt.xlabel('$M_{BH}$ [$M_\odot$]')
    plt.ylabel('Damping timescale $\\tau$ [Gyr]')
    plt.title('BH sinking timescale vs BH mass')
    plt.grid(True, alpha=0.3)
    plt.tight_layout()
    plt.show()